   [B('¿Hay cuerpo envolvente?',engulf,'Sí, contiene el cuerpo previo','No contiene todo el cuerpo previo',`${euro(al)}–${euro(ah)} y ${euro(bl)}–${euro(bh)}.`),B('¿Hay rango interior?',insideRange,'Sí, los extremos quedan dentro','No, algún extremo queda fuera',`${euro(a.l)}–${euro(a.h)} y ${euro(b.l)}–${euro(b.h)}.`),B('¿Los sentidos son opuestos?',(a.c-a.o)*(b.c-b.o)<0,'Las dos velas tienen sentidos opuestos','No tienen sentidos opuestos','Comprueba cada apertura y cierre sin cambiar la definición.')]
